package com.aoo.bcg.mahjong;
import com.aoo.bcg.gamespi.GameCommandRequest;import java.util.List;import java.util.Map;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
final class MahjongAuthoritativeSessionTest{
 @Test void routesCommandsAndHidesOtherHands(){var s=new MahjongAuthoritativeSession(1,10,4,7,new StandardMahjongFamily(StandardMahjongConfig.defaults()));s.execute(req("common.room.join_req","j1",1,"10",0));s.execute(req("common.room.join_req","j2",2,"11",1));s.execute(req("mahjong.standard.start_req","s",3,"10",0));@SuppressWarnings("unchecked")var seats=(Map<Integer,Object>)s.viewFor(10).get("seats");@SuppressWarnings("unchecked")var own=(Map<String,Object>)seats.get(0);@SuppressWarnings("unchecked")var other=(Map<String,Object>)seats.get(1);assertTrue(((List<?>)own.get("cards")).stream().anyMatch(v->((Number)v).intValue()!=0));assertTrue(((List<?>)other.get("cards")).stream().allMatch(v->((Number)v).intValue()==0));assertThrows(SecurityException.class,()->s.execute(req("mahjong.standard.draw_req","d",4,"11",0)));}
 @Test void startUsesSharedDealerAndDealInvariants(){var s=new MahjongAuthoritativeSession(2,20,4,9,new StandardMahjongFamily(StandardMahjongConfig.defaults()),"rules-v");s.execute(reqForVersion(2,"rules-v","common.room.join_req","j1",1,"20",0));s.execute(reqForVersion(2,"rules-v","common.room.join_req","j2",2,"21",1));s.execute(reqForVersion(2,"rules-v","mahjong.standard.start_req","s",3,"20",0));MahjongState state=(MahjongState)s.authoritativeState().get("state");assertEquals(0,state.currentSeat());assertTrue(state.currentSeatHasDrawn());assertEquals(14,state.hands().get(0).size());assertEquals(13,state.hands().get(1).size());assertEquals(136,state.wall().size()+state.hands().values().stream().mapToInt(List::size).sum());int tile=state.hands().get(0).get(0);s.execute(new GameCommandRequest("mahjong.standard.discard_req","x",4,2,1,"rules-v","20",0,Map.of("tile",tile)));}
 @Test void flowerDealIsReconnectSafeAndReplacementViewIsPrivate()throws Exception{var standard=new StandardMahjongFamily(StandardMahjongConfig.defaults());MahjongRuleFamily flowers=new MahjongRuleFamily(){public String familyCode(){return "flowers";}public MahjongRuleSet<MahjongState>ruleSet(){return standard.ruleSet();}public MahjongTileSet tileSet(String version){return MahjongTileSet.standardWithFlowers(version);}};var s=new MahjongAuthoritativeSession(4,40,4,3,flowers,"flower-v");s.execute(reqForVersion(4,"flower-v","common.room.join_req","j1",1,"40",0));s.execute(reqForVersion(4,"flower-v","common.room.join_req","j2",2,"41",1));s.execute(reqForVersion(4,"flower-v","mahjong.standard.start_req","s",3,"40",0));var authority=s.authoritativeState();MahjongState state=(MahjongState)authority.get("state");@SuppressWarnings("unchecked")List<Integer>revealed=(List<Integer>)authority.get("openingFlowers");assertFalse(revealed.isEmpty());assertTrue(state.hands().values().stream().flatMap(List::stream).noneMatch(flowers.tileSet("flower-v")::isFlower));assertEquals(144,state.wall().size()+revealed.size()+state.hands().values().stream().mapToInt(List::size).sum());assertEquals(revealed.size(),((List<?>)authority.get("openingReplacements")).size());assertTrue(s.invariantViolations().isEmpty());var mapper=new com.fasterxml.jackson.databind.ObjectMapper();@SuppressWarnings("unchecked")Map<String,Object>json=mapper.readValue(mapper.writeValueAsString(authority),Map.class);var restored=MahjongAuthoritativeSession.restore(json,flowers);assertEquals(authority,restored.authoritativeState());@SuppressWarnings("unchecked")List<MahjongRegionalRules.ReplacementEvent>events=(List<MahjongRegionalRules.ReplacementEvent>)restored.authoritativeState().get("openingReplacements");for(int index=0;index<events.size();index++){var event=events.get(index);long owner=event.seat()==0?40:41,other=event.seat()==0?41:40;@SuppressWarnings("unchecked")List<Map<String,Object>>ownView=(List<Map<String,Object>>)restored.viewFor(owner).get("openingReplacements");@SuppressWarnings("unchecked")List<Map<String,Object>>otherView=(List<Map<String,Object>>)restored.viewFor(other).get("openingReplacements");assertEquals(event.replacementTile(),ownView.get(index).get("replacementTile"));assertEquals(0,otherView.get(index).get("replacementTile"));assertEquals(event.flowerTile(),otherView.get(index).get("flowerTile"));}}
 @Test void rejectsCommandForAnotherRoomOrPlayVersion(){var s=new MahjongAuthoritativeSession(5,50,4,1,new StandardMahjongFamily(StandardMahjongConfig.defaults()),"frozen");assertThrows(IllegalArgumentException.class,()->s.execute(reqForVersion(6,"frozen","common.room.join_req","x",1,"50",0)));assertThrows(IllegalArgumentException.class,()->s.execute(reqForVersion(5,"other","common.room.join_req","x",1,"50",0)));}
 @Test void restoresDatabaseShapedAuthority()throws Exception{var family=new StandardMahjongFamily(StandardMahjongConfig.defaults());var original=new MahjongAuthoritativeSession(3,30,4,17,family);original.execute(reqFor(3,"common.room.join_req","j1",1,"30",0));original.execute(reqFor(3,"common.room.join_req","j2",2,"31",1));original.execute(reqFor(3,"mahjong.standard.start_req","s",3,"30",0));var mapper=new com.fasterxml.jackson.databind.ObjectMapper();@SuppressWarnings("unchecked")Map<String,Object>saved=mapper.readValue(mapper.writeValueAsString(original.authoritativeState()),Map.class);var restored=MahjongAuthoritativeSession.restore(saved,family);assertEquals(original.authoritativeState(),restored.authoritativeState());assertEquals(original.viewFor(30),restored.viewFor(30));}
 @Test void settlementUsesFrozenVersionAndDetailSurvivesJsonRestore()throws Exception{Map<String,Object>state=Map.of("wall",List.of(),"hands",Map.of(0,List.of(),1,List.of()),"currentSeat",0,"currentSeatHasDrawn",false,"lastDiscard",-1,"lastDiscardSeat",-1,"window",Map.of("candidates",Map.of()),"finished",true,"winnerSeat",0);Map<String,Object>saved=Map.of("roomId",8,"ownerId",80,"seatLimit",2,"seed",1,"playVersion","frozen-v","players",Map.of(0,80,1,81),"state",state,"operationDeadline",com.aoo.bcg.gamespi.time.OperationDeadline.none().toMap());var family=new StandardMahjongFamily(StandardMahjongConfig.defaults());var session=MahjongAuthoritativeSession.restore(saved,family);assertThrows(IllegalArgumentException.class,()->session.settlement(1,"other-v"));session.settlement(1,"frozen-v");var detail=(MahjongRegionalRules.SettlementDetail)session.authoritativeState().get("settlementDetail");assertEquals(Map.of(0,1L,1,-1L),detail.totals());assertEquals("AUTHORITATIVE_ROUND",detail.lines().get(0).source());var mapper=new com.fasterxml.jackson.databind.ObjectMapper();@SuppressWarnings("unchecked")Map<String,Object>json=mapper.readValue(mapper.writeValueAsString(session.authoritativeState()),Map.class);assertEquals(session.authoritativeState(),MahjongAuthoritativeSession.restore(json,family).authoritativeState());}
 @Test void readyIsSeatAuthorizedAndSurvivesAuthorityRestore()throws Exception{var family=new StandardMahjongFamily(StandardMahjongConfig.defaults());var session=new MahjongAuthoritativeSession(9,90,4,1,family);session.execute(reqFor(9,"common.room.join_req","j",1,"90",0));assertThrows(SecurityException.class,()->session.execute(reqFor(9,"common.room.ready_req","bad",2,"91",0)));session.execute(reqFor(9,"common.room.ready_req","ready",3,"90",0));assertEquals(List.of(0),session.authoritativeState().get("readySeats"));var mapper=new com.fasterxml.jackson.databind.ObjectMapper();@SuppressWarnings("unchecked")Map<String,Object>json=mapper.readValue(mapper.writeValueAsString(session.authoritativeState()),Map.class);assertEquals(List.of(0),MahjongAuthoritativeSession.restore(json,family).authoritativeState().get("readySeats"));}
 private static GameCommandRequest req(String id,String request,long seq,String player,int seat){return new GameCommandRequest(id,request,seq,1,1,"v1",player,seat,Map.of());}
 private static GameCommandRequest reqFor(long room,String id,String request,long seq,String player,int seat){return new GameCommandRequest(id,request,seq,room,1,"v1",player,seat,Map.of());}
 private static GameCommandRequest reqForVersion(long room,String version,String id,String request,long seq,String player,int seat){return new GameCommandRequest(id,request,seq,room,1,version,player,seat,Map.of());}
}
